use std::collections::{HashMap, HashSet};

use naratama_model::{CountryId, GroupTable, TeamId};
use rand::rngs::StdRng;
use rand::seq::SliceRandom;
use rand::{Rng, SeedableRng};
use serde::{Deserialize, Serialize};

/// One fixture generated by a pure scheduler before persistence.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct FixtureSlot {
    pub round: i32,
    pub leg: i32,
    pub home: TeamId,
    pub away: TeamId,
    pub group_id: Option<i32>,
}

/// Circle-method round-robin with deterministic simulated-annealing home-away balancing.
pub struct RoundRobinScheduler;

impl RoundRobinScheduler {
    #[must_use]
    pub fn schedule(
        team_ids: &[TeamId],
        double_round: bool,
        optimize_home_away: bool,
        rng: Option<&mut StdRng>,
    ) -> Vec<FixtureSlot> {
        let mut ids = unique_team_ids(team_ids);
        if ids.len() < 2 {
            return Vec::new();
        }
        let mut rng_salt = None;
        if let Some(r) = rng {
            ids.shuffle(r);
            rng_salt = Some(r.gen::<u64>());
        }

        let pairings = circle_rounds(&ids);
        let half_rounds = pairings.len();
        let mut first_home: Vec<Vec<bool>> = pairings
            .iter()
            .enumerate()
            .map(|(r, row)| vec![r % 2 == 1; row.len()])
            .collect();

        if optimize_home_away {
            optimise_orientations(&pairings, &mut first_home, &ids, double_round, rng_salt);
        }

        let mut slots = Vec::with_capacity(
            pairings.iter().map(Vec::len).sum::<usize>() * if double_round { 2 } else { 1 },
        );
        for (r, row) in pairings.iter().enumerate() {
            for (i, &(a, b)) in row.iter().enumerate() {
                let (home, away) = if first_home[r][i] { (a, b) } else { (b, a) };
                slots.push(FixtureSlot {
                    round: r as i32 + 1,
                    leg: 1,
                    home,
                    away,
                    group_id: None,
                });
            }
        }
        if !double_round {
            return slots;
        }

        for (r, row) in pairings.iter().enumerate() {
            for (i, &(a, b)) in row.iter().enumerate() {
                let (home, away) = if first_home[r][i] { (b, a) } else { (a, b) };
                slots.push(FixtureSlot {
                    round: (r + half_rounds) as i32 + 1,
                    leg: 2,
                    home,
                    away,
                    group_id: None,
                });
            }
        }
        slots
    }
}

/// Classic circle method; `None` represents a BYE for odd fields.
fn circle_rounds(team_ids: &[TeamId]) -> Vec<Vec<(TeamId, TeamId)>> {
    let mut ring: Vec<Option<TeamId>> = team_ids.iter().copied().map(Some).collect();
    if ring.len() % 2 == 1 {
        ring.push(None);
    }
    let n = ring.len();
    let mut rounds = Vec::with_capacity(n - 1);
    for _ in 0..(n - 1) {
        let mut pairs = Vec::with_capacity(n / 2);
        for i in 0..(n / 2) {
            if let (Some(a), Some(b)) = (ring[i], ring[n - 1 - i]) {
                pairs.push((a, b));
            }
        }
        rounds.push(pairs);
        if let Some(last) = ring.pop() {
            ring.insert(1, last);
        }
    }
    rounds
}

#[allow(clippy::too_many_lines)]
fn optimise_orientations(
    pairings: &[Vec<(TeamId, TeamId)>],
    first_home: &mut [Vec<bool>],
    ids: &[TeamId],
    double_round: bool,
    rng_salt: Option<u64>,
) {
    let team_count = ids.len();
    let rounds = pairings.len();
    if team_count < 2 || rounds == 0 {
        return;
    }

    let index_of: HashMap<TeamId, usize> = ids.iter().enumerate().map(|(i, &id)| (id, i)).collect();

    let mut team_first_counts = vec![0usize; team_count];
    let mut pair_first_idx = Vec::with_capacity(rounds);
    let mut pair_second_idx = Vec::with_capacity(rounds);
    let mut pair_first_pos = Vec::with_capacity(rounds);
    let mut pair_second_pos = Vec::with_capacity(rounds);
    let mut variables = 0usize;

    for row in pairings {
        variables += row.len();
        let mut fa = Vec::with_capacity(row.len());
        let mut fb = Vec::with_capacity(row.len());
        let mut pa = Vec::with_capacity(row.len());
        let mut pb = Vec::with_capacity(row.len());
        for &(a_id, b_id) in row {
            let a = index_of[&a_id];
            let b = index_of[&b_id];
            fa.push(a);
            fb.push(b);
            pa.push(team_first_counts[a]);
            team_first_counts[a] += 1;
            pb.push(team_first_counts[b]);
            team_first_counts[b] += 1;
        }
        pair_first_idx.push(fa);
        pair_second_idx.push(fb);
        pair_first_pos.push(pa);
        pair_second_pos.push(pb);
    }
    if variables == 0 {
        return;
    }

    let mut work_seqs: Vec<Vec<i8>> = team_first_counts
        .iter()
        .map(|&c| vec![0; if double_round { c * 2 } else { c }])
        .collect();
    let mut work_scores = vec![0i32; team_count];

    let fill_sequences = |orient: &[Vec<bool>], seqs: &mut [Vec<i8>], scores: &mut [i32]| {
        for r in 0..rounds {
            for i in 0..orient[r].len() {
                let a = pair_first_idx[r][i];
                let b = pair_second_idx[r][i];
                let pa = pair_first_pos[r][i];
                let pb = pair_second_pos[r][i];
                let va = if orient[r][i] { 1 } else { -1 };
                let vb = -va;
                seqs[a][pa] = va;
                seqs[b][pb] = vb;
                if double_round {
                    seqs[a][pa + team_first_counts[a]] = -va;
                    seqs[b][pb + team_first_counts[b]] = -vb;
                }
            }
        }
        for t in 0..team_count {
            scores[t] = team_score(&seqs[t], team_first_counts[t], double_round);
        }
    };

    fill_sequences(first_home, &mut work_seqs, &mut work_scores);
    let mut score: i32 = work_scores.iter().sum();
    if score == 0 {
        return;
    }

    let mut seed: u64 = 0x5EED;
    for &id in ids {
        seed = (seed.wrapping_mul(31).wrapping_add(id.get().unsigned_abs())) & 0x7fff_ffff;
    }
    if let Some(salt) = rng_salt {
        seed ^= salt;
    }

    let iterations = (14_000 + variables * 180).clamp(14_000, 42_000);

    for restart in 0..3_u64 {
        if score == 0 {
            break;
        }
        let mut rng = StdRng::seed_from_u64(seed.wrapping_add(restart * 7919));
        let mut current: Vec<Vec<bool>> = first_home.to_vec();
        fill_sequences(&current, &mut work_seqs, &mut work_scores);
        let mut current_score: i32 = work_scores.iter().sum();
        let mut best_score = current_score;
        let mut best = current.clone();
        let mut temperature = 3.0_f64;

        for _ in 0..iterations {
            let r = rng.gen_range(0..rounds);
            let row_len = pairings[r].len();
            if row_len == 0 {
                continue;
            }
            let i = rng.gen_range(0..row_len);

            let a = pair_first_idx[r][i];
            let b = pair_second_idx[r][i];
            let pa = pair_first_pos[r][i];
            let pb = pair_second_pos[r][i];
            let len_a = team_first_counts[a];
            let len_b = team_first_counts[b];

            let flipped = !current[r][i];
            current[r][i] = flipped;
            let va: i8 = if flipped { 1 } else { -1 };
            let vb: i8 = -va;
            work_seqs[a][pa] = va;
            work_seqs[b][pb] = vb;
            if double_round {
                work_seqs[a][pa + len_a] = -va;
                work_seqs[b][pb + len_b] = -vb;
            }

            let new_a = team_score(&work_seqs[a], len_a, double_round);
            let new_b = team_score(&work_seqs[b], len_b, double_round);
            let delta = (new_a - work_scores[a]) + (new_b - work_scores[b]);

            if delta <= 0 || rng.gen::<f64>() < (-f64::from(delta) / temperature.max(0.05)).exp() {
                work_scores[a] = new_a;
                work_scores[b] = new_b;
                current_score += delta;
                if current_score < best_score {
                    best_score = current_score;
                    best.clone_from(&current);
                    if best_score == 0 {
                        break;
                    }
                }
            } else {
                current[r][i] = !flipped;
                work_seqs[a][pa] = -va;
                work_seqs[b][pb] = -vb;
                if double_round {
                    work_seqs[a][pa + len_a] = va;
                    work_seqs[b][pb + len_b] = vb;
                }
            }
            temperature = (temperature * 0.99992).max(0.02);
        }

        if best_score < score {
            first_home.clone_from_slice(&best);
            score = best_score;
        }
        seed = (seed.wrapping_mul(1_103_515_245).wrapping_add(12_345)) & 0x7fff_ffff;
    }
}

fn team_score(full: &[i8], first_half_len: usize, double_round: bool) -> i32 {
    let full_len = full.len();
    if full_len == 0 {
        return 0;
    }
    let mut score = 0i32;
    let mut run = 1i32;
    let mut prev = full[0];

    for &cur in &full[1..] {
        if cur == prev {
            run += 1;
        } else {
            if run > 2 {
                let d = run - 2;
                score += d * d * 100;
            }
            run = 1;
            prev = cur;
        }
    }
    if run > 2 {
        let d = run - 2;
        score += d * d * 100;
    }

    if full_len >= 5 {
        let mut window: i32 = full[..5].iter().map(|&v| i32::from(v)).sum();
        let excess = window.abs() - 1;
        if excess > 0 {
            score += excess * excess * 4;
        }
        for i in 5..full_len {
            window += i32::from(full[i]) - i32::from(full[i - 5]);
            let excess = window.abs() - 1;
            if excess > 0 {
                score += excess * excess * 4;
            }
        }
    }

    if !double_round {
        let sum: i32 = full[..first_half_len].iter().map(|&v| i32::from(v)).sum();
        let imbalance = sum.abs();
        if imbalance > 1 {
            let d = imbalance - 1;
            score += d * d * 50;
        }
    }
    score
}

#[derive(Debug, Clone)]
pub struct LeaguePhaseSchedule {
    pub fixtures: Vec<FixtureSlot>,
    pub opponent_rounds: usize,
}

/// UEFA-style league phase scheduler: exact opponent count and exact H/A split via
/// Hierholzer Eulerian orientation + hill-climb fallback.
pub struct LeaguePhaseScheduler;

impl LeaguePhaseScheduler {
    #[must_use]
    pub fn generate(
        team_ids: &[TeamId],
        opponents: usize,
        home_matches: Option<usize>,
        association_of: Option<&HashMap<TeamId, CountryId>>,
    ) -> LeaguePhaseSchedule {
        let ids = unique_team_ids(team_ids);
        if ids.len() < 2 || opponents == 0 {
            return LeaguePhaseSchedule {
                fixtures: Vec::new(),
                opponent_rounds: 0,
            };
        }
        let playable_opponents = opponents.min(ids.len() - 1);
        let target_home = home_matches.unwrap_or(playable_opponents / 2);

        let all_rounds = circle_rounds(&ids);
        let mut best_offset = 0usize;
        let mut best_conflicts = usize::MAX;
        for offset in 0..all_rounds.len() {
            let mut conflicts = 0usize;
            if let Some(assoc) = association_of {
                for i in 0..playable_opponents {
                    for &(a, b) in &all_rounds[(offset + i) % all_rounds.len()] {
                        if let (Some(ca), Some(cb)) = (assoc.get(&a), assoc.get(&b)) {
                            if ca == cb {
                                conflicts += 1;
                            }
                        }
                    }
                }
            }
            if conflicts < best_conflicts {
                best_conflicts = conflicts;
                best_offset = offset;
            }
        }

        let selected: Vec<&Vec<(TeamId, TeamId)>> = (0..playable_opponents)
            .map(|i| &all_rounds[(best_offset + i) % all_rounds.len()])
            .collect();
        let home_first = orient_league_phase(&selected, &ids, target_home);

        let mut fixtures = Vec::new();
        for (r, round_pairs) in selected.iter().enumerate() {
            for &(a, b) in *round_pairs {
                let lower_home = *home_first.get(&edge_key(a, b)).unwrap_or(&true);
                let first_is_home = if a < b { lower_home } else { !lower_home };
                fixtures.push(FixtureSlot {
                    round: r as i32 + 1,
                    leg: 1,
                    home: if first_is_home { a } else { b },
                    away: if first_is_home { b } else { a },
                    group_id: None,
                });
            }
        }

        LeaguePhaseSchedule {
            fixtures,
            opponent_rounds: selected.len(),
        }
    }
}

fn edge_key(a: TeamId, b: TeamId) -> (TeamId, TeamId) {
    if a < b {
        (a, b)
    } else {
        (b, a)
    }
}

fn orient_league_phase(
    rounds: &[&Vec<(TeamId, TeamId)>],
    ids: &[TeamId],
    target_home: usize,
) -> HashMap<(TeamId, TeamId), bool> {
    let mut edges = Vec::new();
    let mut adjacency: HashMap<TeamId, Vec<usize>> =
        ids.iter().map(|&id| (id, Vec::new())).collect();

    for round_pairs in rounds {
        for &(a, b) in *round_pairs {
            let idx = edges.len();
            edges.push((a, b));
            if let Some(list) = adjacency.get_mut(&a) {
                list.push(idx);
            }
            if let Some(list) = adjacency.get_mut(&b) {
                list.push(idx);
            }
        }
    }

    let mut orientation = HashMap::new();
    let mut used = vec![false; edges.len()];

    for &start in ids {
        if adjacency
            .get(&start)
            .is_none_or(|adj| adj.iter().all(|&e| used[e]))
        {
            continue;
        }
        let mut stack = vec![start];
        let mut traversed = Vec::new();
        while let Some(&v) = stack.last() {
            let next_edge = adjacency
                .get(&v)
                .and_then(|adj| adj.iter().copied().find(|&e| !used[e]));
            let Some(edge_idx) = next_edge else {
                stack.pop();
                continue;
            };
            used[edge_idx] = true;
            traversed.push((edge_idx, v));
            let (a, b) = edges[edge_idx];
            stack.push(if v == a { b } else { a });
        }
        for (edge_idx, from) in traversed {
            let (a, b) = edges[edge_idx];
            let low = a.min(b);
            orientation.insert(edge_key(a, b), from == low);
        }
    }

    let mut homes: HashMap<TeamId, i32> = ids.iter().map(|&id| (id, 0)).collect();
    let mut key_pairs = Vec::with_capacity(edges.len());
    for &(a, b) in &edges {
        let key = edge_key(a, b);
        let low_home = *orientation.entry(key).or_insert(true);
        key_pairs.push((key, key.0, key.1));
        let host = if low_home { key.0 } else { key.1 };
        *homes.entry(host).or_insert(0) += 1;
    }

    let target = target_home as i32;
    let balanced = orientation.len() == edges.len()
        && ids
            .iter()
            .all(|id| homes.get(id).copied().unwrap_or(0) == target);
    if balanced || key_pairs.is_empty() {
        return orientation;
    }

    let mut score: i32 = ids
        .iter()
        .map(|id| {
            let d = homes.get(id).copied().unwrap_or(0) - target;
            d * d
        })
        .sum();
    for it in 0..20_000 {
        if score == 0 {
            break;
        }
        let (key, a, b) = key_pairs[it % key_pairs.len()];
        let old = orientation[&key];
        let (old_home, new_home) = if old { (a, b) } else { (b, a) };
        let h_old = homes[&old_home];
        let h_new = homes[&new_home];
        let delta = ((h_old - 1 - target).pow(2) + (h_new + 1 - target).pow(2))
            - ((h_old - target).pow(2) + (h_new - target).pow(2));
        if delta <= 0 {
            homes.insert(old_home, h_old - 1);
            homes.insert(new_home, h_new + 1);
            orientation.insert(key, !old);
            score += delta;
        }
    }

    orientation
}

/// Distributes seeded teams snake-style across `group_count` balanced groups.
#[must_use]
pub fn snake_groups(
    seeded_ids: &[TeamId],
    group_size: usize,
    requested_groups: usize,
) -> Vec<Vec<TeamId>> {
    let ids = unique_team_ids(seeded_ids);
    if ids.is_empty() {
        return Vec::new();
    }
    let size = group_size.max(2);
    let natural = ids.len().div_ceil(size);
    let count = if requested_groups > 0 {
        requested_groups.min(natural)
    } else {
        natural
    }
    .max(1);

    let mut groups = vec![Vec::new(); count];
    for (i, &id) in ids.iter().enumerate() {
        let round = i / count;
        let slot = i % count;
        let idx = if round % 2 == 0 {
            slot
        } else {
            count - 1 - slot
        };
        groups[idx].push(id);
    }
    groups
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct KnockoutPlan {
    pub bracket_size: usize,
    pub pairs: Vec<(TeamId, TeamId)>,
    pub byes: Vec<TeamId>,
}

impl KnockoutPlan {
    #[must_use]
    pub const fn rounds_to_final(&self) -> usize {
        if self.bracket_size <= 1 {
            0
        } else {
            (self.bracket_size.bit_width() - 1) as usize
        }
    }

    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.pairs.is_empty() && self.byes.is_empty()
    }
}

pub struct KnockoutScheduler;

impl KnockoutScheduler {
    #[must_use]
    pub fn plan_opening_round(
        entrants: &[TeamId],
        use_byes: bool,
        trim_to_power_of_two: bool,
        field_size: Option<usize>,
    ) -> KnockoutPlan {
        let ids = unique_team_ids(entrants);
        if ids.is_empty() {
            return KnockoutPlan {
                bracket_size: 0,
                pairs: Vec::new(),
                byes: Vec::new(),
            };
        }
        if trim_to_power_of_two || !use_byes {
            let limit = field_size.map_or(ids.len(), |f| ids.len().min(f));
            let bracket = largest_power_of_two(limit);
            let field = &ids[..bracket.min(ids.len())];
            return KnockoutPlan {
                bracket_size: bracket,
                pairs: pair_seeded(field),
                byes: Vec::new(),
            };
        }

        let bracket = ids.len().next_power_of_two();
        let bye_count = bracket - ids.len();
        let byes = ids[..bye_count].to_vec();
        let playing = &ids[bye_count..];
        KnockoutPlan {
            bracket_size: bracket,
            pairs: pair_seeded(playing),
            byes,
        }
    }

    #[must_use]
    pub fn pair_next_round(survivors: &[TeamId]) -> KnockoutPlan {
        let ids = unique_team_ids(survivors);
        if ids.len() <= 1 {
            return KnockoutPlan {
                bracket_size: ids.len(),
                pairs: Vec::new(),
                byes: ids,
            };
        }
        let (playing, byes) = if ids.len() % 2 == 1 {
            (&ids[..ids.len() - 1], vec![ids[ids.len() - 1]])
        } else {
            (ids.as_slice(), Vec::new())
        };
        KnockoutPlan {
            bracket_size: ids.len().next_power_of_two(),
            pairs: pair_seeded(playing),
            byes,
        }
    }

    /// Cross-group knockout pairing keeping same-group teams in opposite bracket halves.
    #[must_use]
    pub fn plan_group_knockout(groups: &[GroupTable], qualifiers_per_group: usize) -> KnockoutPlan {
        if qualifiers_per_group == 0 || groups.is_empty() {
            return KnockoutPlan {
                bracket_size: 0,
                pairs: Vec::new(),
                byes: Vec::new(),
            };
        }
        if qualifiers_per_group != 2 || groups.len() < 2 || groups.len() % 2 == 1 {
            let mut qualified = Vec::new();
            for place in 0..qualifiers_per_group {
                if place % 2 == 1 {
                    for g in groups.iter().rev() {
                        if let Some(row) = g.rows.get(place) {
                            qualified.push(row.team_id);
                        }
                    }
                } else {
                    for g in groups {
                        if let Some(row) = g.rows.get(place) {
                            qualified.push(row.team_id);
                        }
                    }
                }
            }
            return Self::plan_opening_round(&qualified, true, false, None);
        }

        let mut pairs = Vec::new();
        let mut paired = HashSet::new();
        let mut try_pair = |a: TeamId, b: TeamId| {
            if a != b && paired.insert(a) && paired.insert(b) {
                pairs.push((a, b));
            }
        };

        for i in (0..groups.len()).step_by(2) {
            if let (Some(w), Some(r)) = (groups[i].rows.first(), groups[i + 1].rows.get(1)) {
                try_pair(w.team_id, r.team_id);
            }
        }
        for i in (0..groups.len()).step_by(2) {
            if let (Some(w), Some(r)) = (groups[i + 1].rows.first(), groups[i].rows.get(1)) {
                try_pair(w.team_id, r.team_id);
            }
        }

        KnockoutPlan {
            bracket_size: groups.len() * qualifiers_per_group,
            pairs,
            byes: Vec::new(),
        }
    }
}

fn pair_seeded(ids: &[TeamId]) -> Vec<(TeamId, TeamId)> {
    (0..(ids.len() / 2))
        .map(|i| (ids[i], ids[ids.len() - 1 - i]))
        .collect()
}

const fn largest_power_of_two(value: usize) -> usize {
    if value <= 1 {
        return value;
    }
    let mut result = 1usize;
    while result * 2 <= value {
        result <<= 1;
    }
    result
}

fn unique_team_ids(ids: &[TeamId]) -> Vec<TeamId> {
    let mut seen = HashSet::with_capacity(ids.len());
    ids.iter().copied().filter(|id| seen.insert(*id)).collect()
}
